public boolean isSignWitnessTrade(Trade trade){
  checkNotNull(trade,"trade must not be null");
  checkNotNull(trade.getOffer(),"offer must not be null");
  Contract contract=checkNotNull(trade.getContract());
  PaymentAccountPayload sellerPaymentAccountPayload=contract.getSellerPaymentAccountPayload();
  AccountAgeWitness myWitness=getMyWitness(sellerPaymentAccountPayload);
  getAccountAgeWitnessUtils().witnessDebugLog(trade,myWitness);
  try {
    return accountIsSigner(myWitness) && !peerHasSignedWitness(trade) && tradeAmountIsSufficient(trade.getAmount());
  } catch (ArithmeticException | DateTimeException | NullPointerException | UnsupportedOperationException | IllegalArgumentException | ClassCastException | KeyConversionException e) {
    // Log the exception and take appropriate action, for example, return false or throw a custom exception
    return false;
  }
}
